// Changing the junk score can cause a reload of the message and it
// should be done after all other changes to minimize UI hiccups.
if (newProperties.junk !== null) {
  const newJunkScore = newProperties.junk
    ? Ci.nsIJunkMailPlugin.IS_SPAM_SCORE
    : Ci.nsIJunkMailPlugin.IS_HAM_SCORE;
  // Note: The IMAP implementation also sets the keyword Junk/NonJunk.
  msgHdr.folder.setJunkScoreForMessages(
    msgs,
    newJunkScore,
    "user",
    -1
  );
}

export class FolderPropertyChangeListener {
  constructor(msgHdr, property) {
    this.mshHdr = msgHdr;
    this.property = property;
    this.task = Promise.withResolvers();
    MailServices.mailSession.AddFolderListener(
      this,
      Ci.nsIFolderListener.propertyFlagChanged
    );
  }

  seen() {
    return this.task.promise;
  }

  /**
   * Implements nsIFolderListener.onFolderPropertyFlagChanged().
   *
   * @param {nsIMsgDBHdr} msgHdr
   * @param {string} property
   * @param {integer} _oldFlag
   * @param {integer} _newFlag
   */
  onFolderPropertyFlagChanged(msgHdr, property, _oldFlag, _newFlag) {
    if (msgHdr == this.mshHdr && property == this.property) {
      MailServices.mailSession.RemoveFolderListener(this);
      this.task.resolve();
    }
